                    return new byte[] { bytes[2] };
                } else if (count >= 2 && bytes[0] == (byte) 0xff && bytes[1] == (byte) 0xfe) {
                    charset = StandardCharsets.UTF_16LE.name();
                    return new byte[] { bytes[2] };
                } else if (count == 3) {
                    return bytes;
                }

                if (count < 0) {
                    return new byte[0];
                }

                byte[] read = new byte[count];
                for (int i = 0; i < count; i++) {
                    read[i] = bytes[i];
                }
                return read;
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

