          absoluteLocalPathToSourceIndex.put(canonicalPath, sourceIndex);
        }
        return Urls.newLocalFileUrl(path);
      }
    }
    return new UrlImpl(baseUrl.getScheme(), baseUrl.getAuthority(), path, null);
