    public static class HandlerWithParserThatReportsSemanticError extends Handler {

        @Override
        public Parser getParser() {
            return task -> {
                RootNode root = super.getParser().parse(task);
                task.getReporter().error(root, TEST_MESSAGE_SEMANTIC_ERROR);
                return root;
            };
        }
    }
