    void testSpecificSuppression() {
        assertWarningsWithFoo(1, "public class Bar {\n"
            + " Integer foo;\n"
            + " void bar() {"
            + "\n" + "  @SuppressWarnings('PMD.NoFoo') Integer foo;\n"
            + " }\n"
            + "}");
