        }
    }

    @Test
    void testClassLevelSuppression() {
        assertNoWarningsWithFoo("@SuppressWarnings('PMD')\n"
                                    + "public class Foo {}");
    }

    private void assertNoWarningsWithFoo(String code) {
        assertWarningsWithFoo(0, code);
    }

