                 PrintWriter printWriter = new PrintWriter(strWriter)) {
                cause.printStackTrace(printWriter);
                project.log(strWriter.toString(), Project.MSG_VERBOSE);
            } catch (IOException e) {
                project.log("Error while closing stream", e, Project.MSG_ERR);
