package net.sourceforge.pmd.ant.internal;

import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import org.apache.tools.ant.Project;
import org.apache.tools.ant.BuildListener;
import org.apache.tools.ant.DefaultLogger;
import org.apache.tools.ant.XmlLogger;
import org.apache.tools.ant.taskdefs.RecorderEntry;
import org.slf4j.event.Level;
import java.util.ArrayList;
import java.util.List;

public class XPathEvaluator {

    public static List<Node> evaluateXPathExpression(XPathDynamicContext dynamicContext, RootXmlNode root, XPathExpression xpathExpression) {
        try {
            List<Node> result = new ArrayList<>();
            for (Object item : xpathExpression.evaluate(dynamicContext)) {
                if (item instanceof NodeWrapper) {
                    NodeWrapper nodeInfo = (NodeWrapper) item;
                    Object domNode = nodeInfo.getUnderlyingNode();
                    if (domNode instanceof org.w3c.dom.Node) {
                        XmlNode wrapped = root.wrap((org.w3c.dom.Node) domNode);
                        result.add(wrapped);
                    }
                }
            }
            return result;
        } catch (XPathException e) {
            throw new ContextedRuntimeException(e)
                .addContextValue("XPath", xpathExpression.toString());
        }
    }
}
