package net.sourceforge.pmd.lang.apex.rule.errorprone;

import net.sourceforge.pmd.lang.apex.ast.ASTBlockStatement;
import net.sourceforge.pmd.lang.apex.ast.ASTMethod;
import net.sourceforge.pmd.lang.apex.ast.ASTUserClass;
import net.sourceforge.pmd.lang.apex.rule.AbstractApexRule;
import net.sourceforge.pmd.lang.apex.rule.internal.Helper;

/**
 * Constructor and init method might contain DML, which constitutes a CSRF
 * vulnerability
 * 
 * @author sergey.gorbaty
 *
 */
public class ApexCSRFRule extends AbstractApexRule {
    public static final String INIT = "init";
    private static final String STATIC_INITIALIZER = "<clinit>";

    public ApexCSRFRule() {
        setProperty(CODECLIMATE_CATEGORIES, "Security");
        setProperty(CODECLIMATE_REMEDIATION_MULTIPLIER, 100);
        setProperty(CODECLIMATE_BLOCK_HIGHLIGHTING, false);
    }

    @Override
    public Object visit(ASTUserClass node, Object data) {
        if (Helper.isTestMethodOrClass(node) || Helper.isSystemLevelClass(node)) {
            return data; // stops all the rules
        }

        return super.visit(node, data);
    }

    @Override
    public Object visit(ASTMethod node, Object data) {
        if (!Helper.isTestMethodOrClass(node)) {
            checkForCSRF(node, data);
        }
        return data;
    }

    @Override
    public Object visit(ASTBlockStatement node, Object data) {
        if (node.jjtGetParent() instanceof ASTUserClass) {
            // initializer block
            if (Helper.foundAnyDML(node)) {
                addViolation(data, node);
            }
        }
        return data;
    }

    /**
     * @param node
     * @param data
     */
    private void checkForCSRF(ASTMethod node, Object data) {
        if (isDMLPresentInConstructor(node, data) || isDMLPresentInInitOrStaticInitializer(node, data)) {
            addViolation(data, node);
        }
    }

    private boolean isDMLPresentInConstructor(ASTMethod node, Object data) {
        if (node.isConstructor()) {
            return Helper.foundAnyDML(node);
        }
        return false;
    }

    private boolean isDMLPresentInInitOrStaticInitializer(ASTMethod node, Object data) {
        String name = node.getImage();
        return (INIT.equalsIgnoreCase(name) || STATIC_INITIALIZER.equals(name)) && Helper.foundAnyDML(node);
    }
}
