        verify(mockCache).checkValidity(any(), any());
        verify(mockCache, times(1)).persist();
        verify(mockCache, times(NUM_DATA_SOURCES)).isUpToDate(any());
    }

    @Test
    void testCacheWithFailure() throws Exception {

        PMDConfiguration config = newConfig();
