        @Override
        public void run() {
          if (!checkDisposed() && !myProgress.isCanceled()) {
            CalcElementsThread currentBgProcess = myCalcElementsThread;
            LOG.assertTrue(currentBgProcess == CalcElementsThread.this, currentBgProcess);

            showCard(cardToShow, 0);

